/* Small, buildless client. All server content is escaped before rendering. */
const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4z M20 4h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-2h3z',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2z',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M22 21v-2a4 4 0 0 0-3-3.87 M16 3a4 4 0 0 1 0 8',user:'M20 21v-2a7 7 0 0 0-14 0v2 M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',check:'M5 12l4 4L19 6',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z M8 12l3 3 5-6',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',video:'M16 8l6-4v16l-6-4 M2 5h14v14H2z',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',mail:'M3 5h18v14H3z M3 5l9 8 9-8',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',plus:'M12 5v14 M5 12h14',edit:'M16 3l5 5-12 12-6 1 1-6z M14 5l5 5',copy:'M9 9h12v12H9z M15 9V3H3v12h6',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',log:'M6 3h12v18H6z M9 7h6 M9 11h6 M9 15h4',logout:'M9 3H3v18h6 M9 12h12 M17 8l4 4-4 4',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',sliders:'M4 4v16 M12 4v16 M20 4v16 M1 8h6 M9 16h6 M17 8h6',external:'M14 3h7v7 M21 3l-12 12 M10 3H3v18h18v-7',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',refresh:'M20 7V2l-3 3a9 9 0 1 0 4 10 M20 7h-5',briefcase:'M3 7h18v14H3z M8 7V3h8v4 M3 12h18 M10 12v3h4v-3'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.book}"/></svg>`;
const labels={pending:'รออนุมัติ',confirmed:'ยืนยันแล้ว',waitlisted:'คิวสำรอง',rejected:'ไม่ผ่านการพิจารณา',cancelled:'ยกเลิกแล้ว',draft:'ฉบับร่าง',open:'เปิดรับสมัคร',full:'ที่นั่งเต็ม',closed:'ปิดรับสมัคร',finished:'สิ้นสุดแล้ว',queued:'รอส่ง',sending:'กำลังส่ง',sent:'ส่งสำเร็จ',failed:'ส่งล้มเหลว',local:'บันทึกในเครื่อง'};
const formatLabels={onsite:'Onsite',online:'Online',hybrid:'Hybrid'};
const badge=status=>`<span class="badge ${esc(status)}">${esc(labels[status]||status)}</span>`;
const fmt=(date,options={day:'numeric',month:'short',year:'numeric'})=>new Intl.DateTimeFormat('th-TH',{timeZone:'Asia/Bangkok',...options}).format(new Date(date));
const time=date=>fmt(date,{hour:'2-digit',minute:'2-digit'});
const number=value=>Number(value||0).toLocaleString('th-TH');
const price=c=>Number(c.price)===0?'<div class="price free">ไม่มีค่าใช้จ่าย<small>เรียนรู้ได้เต็มที่ ฟรีตลอดหลักสูตร</small></div>':`<div class="price">฿${number(c.price)}<small>ค่าลงทะเบียนต่อท่าน · รอตรวจสอบการชำระเงิน</small></div>`;
let config={};let user=null;let renderVersion=0;let allCourses=[];let courseFormat='';let statusCredentials={};let toastTimer;

async function api(path,{method='GET',body,headers={}}={}){
  const res=await fetch(path,{method,credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{}),...(method!=='GET'?{'X-CSRF-Token':config.csrf_token||''}:{}),...headers},...(body?{body:JSON.stringify(body)}:{})});
  let result;try{result=await res.json();}catch{throw new Error('ไม่สามารถเชื่อมต่อระบบได้ กรุณาลองใหม่');}
  if(!result.ok){const e=new Error(result.error?.message||'ระบบขัดข้อง');Object.assign(e,result.error,{status:res.status});throw e;}
  return result.data;
}
function toast(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4500);}
function go(path){history.pushState({},'',path);void render();window.scrollTo({top:0,behavior:'instant'});}
function brand(){return `<a class="brand" href="/" data-link><span class="brand-mark">${icon('book')}</span><span class="brand-name">เรียนรู้<small>LEARN & GROW</small></span></a>`;}
function shell(){
  const path=location.pathname;
  $('#header').innerHTML=`<div class="header-inner">${brand()}<nav class="main-nav" aria-label="เมนูหลัก"><a href="/" data-link class="${path==='/'||path.startsWith('/courses')?'active':''}">สำรวจหลักสูตร</a><a href="/registrations" data-link class="${path.startsWith('/registrations')?'active':''}">ตรวจสอบการสมัคร</a></nav><div class="header-actions">${user?`<a class="staff-link" href="/admin" data-link><span class="avatar">${esc(user.name.slice(0,1))}</span><span class="label">${esc(user.name)}</span></a>`:`<a class="staff-link" href="/admin/login" data-link>${icon('lock')}<span class="label">สำหรับเจ้าหน้าที่</span></a>`}</div></div>`;
  $('#footer').innerHTML=`<div class="footer-inner">${brand()}<span>พื้นที่การเรียนรู้ เพื่อทุกก้าวของการเติบโต</span><div class="footer-links"><a href="/privacy" data-link>นโยบายข้อมูลส่วนบุคคล</a><a href="/admin" data-link>สำหรับเจ้าหน้าที่</a><span>© ${new Date().getFullYear()} เรียนรู้</span></div></div>`;
  if(user){const button=document.createElement('button');button.className='button ghost small';button.type='button';button.setAttribute('aria-label','ออกจากระบบบัญชี');button.title='ออกจากระบบ';button.innerHTML=icon('logout');button.addEventListener('click',async()=>{try{await api('/api/admin/logout',{method:'POST',body:{}});user=null;go('/admin/login');}catch(e){toast(e.message);}});$('.header-actions').append(button);}
}
const breadcrumb=(items)=>`<nav class="breadcrumb" aria-label="เส้นทางนำทาง"><a href="/" data-link>หน้าแรก</a>${items.map(i=>`<span>${i.href?`<a href="${esc(i.href)}" data-link>${esc(i.label)}</a>`:esc(i.label)}</span>`).join('')}</nav>`;
const empty=(title,message,action='')=>`<div class="empty-state">${icon('search')}<h2>${esc(title)}</h2><p>${esc(message)}</p>${action}</div>`;
const formError=()=>'<div class="form-error notice error" role="alert" tabindex="-1"></div>';
function field(name,label,type='text',options={}){
  const {required=false,value='',placeholder='',hint='',full=false,attrs='',choices=[]}=options;
  const id=`field-${name}`;let input;
  if(type==='select')input=`<select name="${esc(name)}" id="${id}" ${required?'required':''} ${attrs}>${choices.map(c=>{const [v,l]=Array.isArray(c)?c:[c,c];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`;}).join('')}</select>`;
  else if(type==='textarea')input=`<textarea name="${esc(name)}" id="${id}" rows="5" ${required?'required':''} ${attrs}>${esc(value)}</textarea>`;
  else input=`<input type="${type}" name="${esc(name)}" id="${id}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${required?'required':''} ${attrs}>`;
  return `<div class="field ${full?'full':''}"><label for="${id}">${esc(label)}${required?' <span class="required" aria-hidden="true">*</span>':''}</label>${input}<p class="field-error" id="error-${esc(name)}"></p>${hint?`<p class="field-hint">${esc(hint)}</p>`:''}</div>`;
}
function showErrors(form,error){
  const alert=$('.form-error',form);if(alert){alert.textContent=error.message;alert.focus();}
  for(const [key,values] of Object.entries(error.fields||{})){const input=form.elements.namedItem(key);const message=form.querySelector(`[id="error-${CSS.escape(key)}"]`);if(input?.setAttribute)input.setAttribute('aria-invalid','true');if(message)message.textContent=values.join(' ');}
}
function submitForm(form,handler){
  form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;
    const button=$('button[type=submit]',form);const before=button?.innerHTML;
    $$('.field-error',form).forEach(e=>e.textContent='');$$('[aria-invalid]',form).forEach(e=>e.removeAttribute('aria-invalid'));const alert=$('.form-error',form);if(alert)alert.textContent='';
    if(button){button.disabled=true;button.textContent='กำลังบันทึก…';}
    try{await handler(new FormData(form),form);}catch(error){showErrors(form,error);}finally{if(button&&button.isConnected){button.disabled=false;button.innerHTML=before;}}
  });
}
async function confirmAction(message,{title='ยืนยันการทำรายการ',reason=false}={}){
  const dialog=$('#confirm-dialog');$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;$('#reason-wrap').hidden=!reason;$('#confirm-reason').value='';dialog.returnValue='';dialog.showModal();
  return new Promise(resolve=>dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'?{reason:$('#confirm-reason').value}:null),{once:true}));
}
function artwork(c,i=0,detail=false){
  const names=[['AI at work','WORK SMARTER'],['Data storytelling','MAKE DATA MATTER'],['Design thinking','IDEAS INTO IMPACT'],['Excel skills','WORK WITH CONFIDENCE']];const [title,tag]=names[i%4];
  return `<div class="course-art art-${i%4} ${detail?'detail-hero':''}">${c.cover_image?`<img src="${esc(c.cover_image)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<div class="art-label"><small>${tag}</small>${title}</div><span class="art-shape" aria-hidden="true"></span>`}<span class="format-overlay">${icon(c.format==='online'?'video':c.format==='hybrid'?'grid':'pin')}${formatLabels[c.format]}</span></div>`;
}
function courseCard(c,i){return `<article class="course-card">${artwork(c,i)}<div class="card-body"><div class="card-topline"><span class="category">พัฒนาทักษะ</span>${c.requires_approval?'<span class="badge pending">พิจารณาการสมัคร</span>':''}</div><h3><a href="/courses/${esc(c.slug)}" data-link>${esc(c.title)}</a></h3><div class="card-meta"><span>${icon('calendar')}${fmt(c.start_at)} · ${time(c.start_at)} น.</span><span>${icon('user')}${esc(c.speaker)}</span><span>${icon(c.format==='online'?'video':'pin')}${esc(c.format==='online'?'เรียนออนไลน์ ผ่านห้องเรียนสด':c.location)}</span><span class="seat-info ${c.remaining<=5?'low':''}">${icon('users')}${c.remaining?`เหลือ ${number(c.remaining)} จาก ${number(c.capacity)} ที่นั่ง`:'ที่นั่งเต็ม · เปิดรับคิวสำรอง'}</span></div><div class="card-footer">${Number(c.price)===0?'<span class="price free">ฟรี<span class="visually-hidden"> ไม่มีค่าใช้จ่าย</span></span>':`<span class="price">฿${number(c.price)}</span>`}<a class="text-link" href="/courses/${esc(c.slug)}" data-link>ดูรายละเอียด ${icon('book')}</a></div></div></article>`;}

async function home(version){
  document.title='สำรวจหลักสูตร — เรียนรู้';
  const courses=await api('/api/courses');if(version!==renderVersion)return;allCourses=courses;courseFormat='';
  $('#main').innerHTML=`<div class="container"><section class="hero"><div class="hero-copy"><div class="eyebrow">${icon('spark')} พื้นที่เล็ก ๆ ของการเติบโตครั้งใหม่</div><h1>เติมทักษะที่ใช่<br>เปิดโอกาสให้<span> </span><em>ตัวคุณเอง</em></h1><p>ค้นพบหลักสูตรและเวิร์กชอปที่ช่วยต่อยอดความสามารถ<br>เรียนรู้กับผู้เชี่ยวชาญ แล้วก้าวไปข้างหน้าด้วยกัน</p><div class="hero-tags"><span>${icon('check')} เรียนรู้จากผู้เชี่ยวชาญ</span><span>${icon('check')} เน้นลงมือทำจริง</span><span>${icon('check')} สมัครง่ายในไม่กี่นาที</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="art-panel"></div><span class="art-star">✦</span><span class="art-dot"></span><span class="float-chip">${icon('spark')} Your next chapter starts here</span></div></section><section class="page-section" aria-labelledby="courses-heading"><div class="section-heading"><div><h2 id="courses-heading">ค้นหาการเรียนรู้ครั้งถัดไป</h2><p>เลือกหลักสูตรที่เหมาะกับความสนใจและเวลาของคุณ</p></div><span class="count-label">ทั้งหมด <strong id="course-count">${courses.length}</strong> หลักสูตร</span></div><form id="search-form" class="filters" role="search"><div class="search-control">${icon('search')}<label class="visually-hidden" for="search">ค้นหาหลักสูตรหรือวิทยากร</label><input id="search" name="search" placeholder="ค้นหาหลักสูตร หรือชื่อวิทยากร…" maxlength="200"></div><label class="visually-hidden" for="filter-date">วันที่อบรม</label><input id="filter-date" type="date" name="date" aria-label="วันที่อบรม"><button class="button primary" type="submit">ค้นหา</button></form><div class="view-bar"><div class="filter-tabs" role="group" aria-label="รูปแบบการอบรม">${[['','ทั้งหมด'],['onsite','Onsite'],['online','Online'],['hybrid','Hybrid']].map(([v,l])=>`<button type="button" class="chip ${!v?'active':''}" data-format="${v}" aria-pressed="${!v}">${v?icon(v==='online'?'video':v==='hybrid'?'grid':'pin'):''}${l}</button>`).join('')}</div><span class="sort-note">${icon('calendar')} เรียงตามวันที่อบรม</span></div><div id="course-results" class="course-grid" aria-live="polite"></div></section><div class="benefit-strip"><div class="benefit"><div class="benefit-icon">${icon('book')}</div><div><strong>เลือกเรียนในแบบของคุณ</strong><p>ทั้งห้องเรียนจริง ออนไลน์ และไฮบริด</p></div></div><div class="benefit"><div class="benefit-icon">${icon('users')}</div><div><strong>ดูแลทุกขั้นตอนการสมัคร</strong><p>ตรวจสอบสถานะ และจัดการได้ด้วยตัวเอง</p></div></div><div class="benefit"><div class="benefit-icon">${icon('shield')}</div><div><strong>ข้อมูลของคุณได้รับการดูแล</strong><p>จำกัดการเข้าถึงข้อมูลส่วนบุคคล</p></div></div></div></div>`;
  const update=()=>{
    const search=$('#search').value.toLowerCase().trim(),date=$('#filter-date').value;
    const items=allCourses.filter(c=>(!courseFormat||c.format===courseFormat)&&(!search||`${c.title} ${c.speaker}`.toLowerCase().includes(search))&&(!date||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(c.start_at))===date));
    $('#course-count').textContent=items.length;$('#course-results').innerHTML=items.length?items.map(c=>courseCard(c,allCourses.indexOf(c))).join(''):empty('ยังไม่พบหลักสูตรที่ตรงใจ','ลองเปลี่ยนคำค้นหา วันที่ หรือรูปแบบการอบรม');
  };
  $('#search-form').addEventListener('submit',e=>{e.preventDefault();update();});$('#search').addEventListener('input',update);$('#filter-date').addEventListener('change',update);
  $$('[data-format]').forEach(button=>button.addEventListener('click',()=>{courseFormat=button.dataset.format;$$('[data-format]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});update();}));update();
}
async function courseDetail(slug,version){
  const c=await api(`/api/courses/${encodeURIComponent(slug)}`);if(version!==renderVersion)return;document.title=`${c.title} — เรียนรู้`;
  $('#main').innerHTML=`<div class="container">${breadcrumb([{label:'หลักสูตร',href:'/'},{label:c.title}])}<div class="detail-layout"><article class="detail-main">${artwork(c,Math.max(0,allCourses.findIndex(x=>x.id===c.id)),true)}<div class="button-row">${badge(c.status)}<span class="category">${formatLabels[c.format]}</span></div><h1 class="page-title">${esc(c.title)}</h1><p class="subtitle">เรียนรู้กับ ${esc(c.speaker)}</p><div class="panel"><h2>เกี่ยวกับหลักสูตร</h2><div class="detail-copy">${esc(c.description)}</div></div></article><aside class="panel detail-aside"><h2>เตรียมพร้อมสำหรับการเรียนรู้</h2>${price(c)}<hr class="divider"><div class="card-meta"><span>${icon('calendar')}<span>${fmt(c.start_at)}<br>${time(c.start_at)} – ${time(c.end_at)} น.${fmt(c.start_at)!==fmt(c.end_at)?`<br>สิ้นสุด ${fmt(c.end_at)}`:''}</span></span><span>${icon('pin')}${esc(c.format==='online'?'อบรมออนไลน์ · ส่งลิงก์หลังยืนยันการสมัคร':c.location)}</span><span>${icon('user')}${esc(c.speaker)}</span><span>${icon('users')}จำนวน ${number(c.capacity)} ที่นั่ง · เหลือ ${number(c.remaining)} ที่</span><span>${icon('clock')}ปิดรับ ${fmt(c.reg_close_at)} ${time(c.reg_close_at)} น.</span></div>${c.requires_approval?'<p class="notice">หลักสูตรนี้ต้องได้รับการอนุมัติจากเจ้าหน้าที่</p>':''}${c.accepting?`<a href="/courses/${esc(c.slug)}/register" data-link class="button primary full">${c.remaining?'ลงทะเบียนอบรม':'เข้าคิวสำรอง'}</a>`:'<button class="button primary full" disabled>ยังไม่เปิดหรือปิดรับสมัครแล้ว</button>'}<p class="field-hint center">ยกเลิกได้ก่อนเริ่มอบรม ${number(c.cancel_deadline_days)} วัน</p></aside></div></div>`;
}
async function registrationForm(slug,version){
  const c=await api(`/api/courses/${encodeURIComponent(slug)}`);if(version!==renderVersion)return;document.title=`ลงทะเบียน ${c.title} — เรียนรู้`;
  if(!c.accepting){$('#main').innerHTML=`<div class="container page-section">${empty('ปิดรับสมัครแล้ว','หลักสูตรนี้ไม่อยู่ในช่วงเวลารับสมัคร',`<a href="/" data-link class="button primary">สำรวจหลักสูตรอื่น</a>`)}</div>`;return;}
  $('#main').innerHTML=`<div class="container"><div class="form-container">${breadcrumb([{label:c.title,href:`/courses/${c.slug}`},{label:'ลงทะเบียน'}])}<h1 class="page-title">${c.remaining?'ลงทะเบียนอบรม':'เข้าคิวสำรอง'}</h1><p class="subtitle">${esc(c.title)} · ${fmt(c.start_at)}</p>${!c.remaining?'<div class="notice warning">ที่นั่งเต็มแล้ว คุณสามารถเข้าคิวสำรอง และจะได้รับอีเมลเมื่อมีที่ว่าง</div>':''}<form id="registration-form">${formError()}<section class="panel form-section"><h2>${icon('user')} ข้อมูลผู้สมัคร</h2><p class="field-hint">ช่องที่มี * จำเป็นต้องกรอก</p><div class="form-grid">${field('title','คำนำหน้า','select',{required:true,choices:[['','เลือกคำนำหน้า'],'นาย','นาง','นางสาว','ดร.','อื่น ๆ']})}<div></div>${field('first_name','ชื่อ','text',{required:true,attrs:'autocomplete="given-name" maxlength="200"'})}${field('last_name','นามสกุล','text',{required:true,attrs:'autocomplete="family-name" maxlength="200"'})}${field('email','อีเมล','email',{required:true,hint:'ใช้รับรหัสการสมัครและข่าวสารเกี่ยวกับหลักสูตร',attrs:'autocomplete="email" maxlength="254"'})}${field('phone','เบอร์โทรศัพท์','tel',{required:true,placeholder:'08xxxxxxxx',attrs:'autocomplete="tel" pattern="0[0-9]{9}" maxlength="10" inputmode="numeric"'})}${field('organization','หน่วยงาน / องค์กร','text',{required:true,attrs:'autocomplete="organization" maxlength="200"'})}${field('position','ตำแหน่ง','text',{required:true,attrs:'autocomplete="organization-title" maxlength="200"'})}</div></section>${c.fields.length?`<section class="panel form-section"><h2>${icon('briefcase')} ข้อมูลเพิ่มเติม</h2><div class="form-grid">${c.fields.map(f=>f.type==='checkbox'?`<div class="field full"><label class="checkbox-label"><input type="checkbox" name="custom_${esc(f.id)}" ${f.is_required?'required':''}>${esc(f.label)}${f.is_required?' *':''}</label><p class="field-error" id="error-custom_${esc(f.id)}"></p></div>`:field(`custom_${f.id}`,f.label,f.type==='select'?'select':'text',{required:f.is_required,choices:[['','เลือกคำตอบ'],...f.options],full:true,attrs:'maxlength="2000"'})).join('')}</div></section>`:''}<section class="panel form-section"><h2>${icon('shield')} การใช้ข้อมูลส่วนบุคคล</h2><label class="checkbox-label"><input type="checkbox" name="pdpa_consent" required><span>ฉันได้อ่านและยอมรับ <a href="/privacy" target="_blank" rel="noopener">นโยบายข้อมูลส่วนบุคคล</a> ยินยอมให้ใช้ข้อมูลเพื่อดำเนินการสมัครและติดต่อเกี่ยวกับการอบรมครั้งนี้ <span class="required">*</span></span></label><p class="field-error" id="error-pdpa_consent"></p><p class="field-hint">ระบบจะบันทึกวันเวลาที่คุณให้ความยินยอม</p></section><div class="honeypot" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><div id="captcha-container"></div><div class="notice">${icon('info')} ${Number(c.price)>0?'หลักสูตรนี้มีค่าลงทะเบียน สถานะจะรอตรวจสอบโดยเจ้าหน้าที่ ระบบชำระเงินออนไลน์อยู่ใน Phase 2':c.requires_approval?'หลังสมัครจะอยู่ในสถานะรออนุมัติ และได้รับอีเมลแจ้งผล':'เมื่อสมัครสำเร็จ คุณจะได้รับรหัสการสมัครและอีเมลแจ้งสถานะ'}</div><div class="button-row"><button class="button primary" type="submit">${c.remaining?'ยืนยันการลงทะเบียน':'ยืนยันเข้าคิวสำรอง'}</button><a class="button secondary" href="/courses/${esc(c.slug)}" data-link>กลับไปดูหลักสูตร</a></div></form></div></div>`;
  let widget;
  if(config.captcha_site_key){
    try{await loadTurnstile();if(version!==renderVersion)return;widget=window.turnstile.render('#captcha-container',{sitekey:config.captcha_site_key,action:'register',language:'th'});}catch{ $('#captcha-container').innerHTML='<p class="notice error">โหลดการยืนยันตัวตนไม่สำเร็จ กรุณาโหลดหน้าใหม่</p>'; }
  }
  submitForm($('#registration-form'),async(data)=>{
    const answers=Object.fromEntries(c.fields.map(f=>[f.id,f.type==='checkbox'?data.has(`custom_${f.id}`):data.get(`custom_${f.id}`)||'']));
    const payload=Object.fromEntries(['title','first_name','last_name','email','phone','organization','position','website'].map(k=>[k,data.get(k)]));
    try{const result=await api(`/api/courses/${c.id}/register`,{method:'POST',body:{...payload,pdpa_consent:data.has('pdpa_consent'),custom_answers:answers,captcha_token:widget!==undefined?window.turnstile.getResponse(widget):undefined}});statusCredentials={token:result.token};go(`/registrations/${result.code}#token=${result.token}`);toast('บันทึกการสมัครเรียบร้อยแล้ว');}
    catch(e){if(widget!==undefined)window.turnstile.reset(widget);throw e;}
  });
}
let turnstilePromise;
function loadTurnstile(){if(window.turnstile)return Promise.resolve();if(!turnstilePromise)turnstilePromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.onload=resolve;script.onerror=()=>{turnstilePromise=null;reject(new Error('โหลด CAPTCHA ไม่สำเร็จ'));};document.head.append(script);});return turnstilePromise;}

async function lookupPage(code='',version=renderVersion){
  document.title='ตรวจสอบการสมัคร — เรียนรู้';
  const fragment=new URLSearchParams(location.hash.slice(1));const token=fragment.get('token')||new URLSearchParams(location.search).get('token');
  if(code&&token){statusCredentials={token};const r=await api(`/api/registrations/${encodeURIComponent(code)}`,{headers:{'X-Registration-Token':token}});if(version===renderVersion)showRegistration(r);return;}
  $('#main').innerHTML=`<div class="container"><div class="narrow"><div class="panel"><div class="login-icon">${icon('search')}</div><h1 class="page-title">ตรวจสอบการสมัคร</h1><p class="subtitle">กรอกรหัสการสมัครและอีเมลที่ใช้สมัคร<br>เพื่อดูสถานะหรือจัดการการสมัครของคุณ</p><form id="lookup-form" class="stack">${formError()}${field('code','รหัสการสมัคร','text',{required:true,value:code,placeholder:'REG-2026-000001',attrs:'pattern="REG-[0-9]{4}-[0-9]{6,}" maxlength="30"'})}${field('email','อีเมลที่ใช้สมัคร','email',{required:true,attrs:'autocomplete="email" maxlength="254"'})}<button type="submit" class="button primary full">ตรวจสอบสถานะ</button></form><p class="field-hint center">รหัสการสมัครอยู่ในหน้าสรุปและอีเมลยืนยันของคุณ</p></div></div></div>`;
  submitForm($('#lookup-form'),async(data)=>{const body={code:data.get('code').trim(),email:data.get('email').trim()};const r=await api('/api/registrations/lookup',{method:'POST',body});statusCredentials={token:r.token};history.replaceState({},'',`/registrations/${encodeURIComponent(body.code)}`);shell();showRegistration(r);});
}
function showRegistration(r){
  const statusText={confirmed:'พร้อมแล้วสำหรับการเรียนรู้',pending:'เราได้รับการสมัครของคุณแล้ว',waitlisted:'คุณอยู่ในคิวสำรองแล้ว',cancelled:'ยกเลิกการสมัครเรียบร้อย',rejected:'แจ้งผลการพิจารณาการสมัคร'}[r.status];
  $('#main').innerHTML=`<div class="container"><div class="form-container">${breadcrumb([{label:'การสมัครของฉัน',href:'/registrations'},{label:r.code}])}<div class="status-header"><div class="status-icon">${icon(r.status==='confirmed'?'check':'mail')}</div><h1>${statusText}</h1><p class="muted">เก็บรหัสนี้ไว้สำหรับตรวจสอบและจัดการการสมัคร</p><div class="registration-code">${esc(r.code)}</div></div><section class="panel form-section"><div class="section-heading"><h2>ข้อมูลการสมัคร</h2>${badge(r.status)}</div><h2>${esc(r.course.title)}</h2><dl class="key-values"><div><dt>ผู้สมัคร</dt><dd>${esc(r.title)}${esc(r.first_name)} ${esc(r.last_name)}</dd></div><div><dt>อีเมล</dt><dd>${esc(r.email)}</dd></div><div><dt>วันเวลาอบรม (กรุงเทพฯ)</dt><dd>${fmt(r.course.start_at)} ${time(r.course.start_at)} – ${time(r.course.end_at)} น.</dd></div><div><dt>สถานที่</dt><dd>${esc(r.course.location||'ออนไลน์')}</dd></div><div><dt>หน่วยงาน / ตำแหน่ง</dt><dd>${esc(r.organization)} · ${esc(r.position)}</dd></div><div><dt>เวลายินยอม PDPA</dt><dd>${fmt(r.pdpa_consented_at)} ${time(r.pdpa_consented_at)} น.</dd></div>${r.status==='waitlisted'?`<div><dt>ลำดับคิวสำรอง</dt><dd>ลำดับที่ ${number(r.waitlist_position)}</dd></div>`:''}</dl>${r.reason?`<div class="notice">เหตุผล: ${esc(r.reason)}</div>`:''}${r.course.online_url?`<a class="button secondary" href="${esc(r.course.online_url)}" target="_blank" rel="noopener noreferrer">${icon('video')} เข้าห้องเรียนออนไลน์</a>`:''}</section><div class="notice">${icon('mail')} ${config.email_mode==='local'?'โหมดพัฒนา: อีเมลถูกบันทึกเป็นไฟล์ใน data/outbox ยังไม่ได้ส่งไปยังกล่องจดหมายจริง':'ระบบจะส่งอีเมลแจ้งรายละเอียดและการเปลี่ยนแปลงสถานะ กรุณาตรวจสอบกล่องจดหมายและโฟลเดอร์สแปม'}</div>${r.can_cancel?`<section class="panel form-section"><h2>จัดการการสมัคร</h2><p class="small-text muted">ยกเลิกได้ก่อนเริ่มอบรม ${number(r.course.cancel_deadline_days)} วัน หากมีคิวสำรอง ที่นั่งจะถูกส่งต่ออัตโนมัติ</p><button id="cancel-registration" class="button danger" type="button">ยกเลิกการสมัคร</button></section>`:''}<a href="/" class="button secondary" data-link>สำรวจหลักสูตรเพิ่มเติม</a></div></div>`;
  $('#cancel-registration')?.addEventListener('click',async()=>{
    if(!await confirmAction('คุณต้องการยกเลิกการสมัครหลักสูตรนี้ใช่ไหม? ที่นั่งจะถูกส่งต่อให้ผู้สมัครคิวสำรอง',{title:'ยกเลิกการสมัคร'}))return;
    const button=$('#cancel-registration');button.disabled=true;
    try{await api(`/api/registrations/${r.code}/cancel`,{method:'POST',body:statusCredentials});r.status='cancelled';r.can_cancel=false;r.waitlist_position=null;showRegistration(r);toast('ยกเลิกการสมัครเรียบร้อยแล้ว');}catch(e){toast(e.message);button.disabled=false;}
  });
}
function loginPage(){
  document.title='เข้าสู่ระบบเจ้าหน้าที่ — เรียนรู้';
  $('#main').innerHTML=`<div class="container"><div class="narrow"><div class="panel"><div class="login-icon">${icon('lock')}</div><h1 class="page-title">ยินดีต้อนรับกลับ</h1><p class="subtitle">เข้าสู่ระบบสำหรับผู้ดูแลและเจ้าหน้าที่</p><form id="login-form" class="stack">${formError()}${field('email','อีเมล','email',{required:true,attrs:'autocomplete="username"'})}${field('password','รหัสผ่าน','password',{required:true,attrs:'autocomplete="current-password" maxlength="100"'})}<button type="submit" class="button primary full">เข้าสู่ระบบ</button></form><p class="field-hint center">บัญชีผู้ใช้สร้างโดยผู้ดูแลระบบขององค์กร</p></div></div></div>`;
  submitForm($('#login-form'),async(data)=>{const result=await api('/api/admin/login',{method:'POST',body:Object.fromEntries(data)});user=result.user;config.csrf_token=result.csrf_token;go('/admin');});
}
function adminShell(content,active='overview'){
  const nav=[['overview','/admin','grid','ภาพรวม'],['courses','/admin/courses','book',user.role==='admin'?'จัดการหลักสูตร':'หลักสูตรและผู้สมัคร'],...(user.role==='admin'?[['users','/admin/users','users','ผู้ใช้ระบบ'],['emails','/admin/emails','mail','การส่งอีเมล'],['audit','/admin/audit','log','ประวัติการทำรายการ']]:[])];
  $('#main').innerHTML=`<div class="admin-shell"><aside class="sidebar"><p class="sidebar-label">WORKSPACE</p><nav class="sidebar-nav" aria-label="เมนูเจ้าหน้าที่">${nav.map(([key,href,ic,label])=>`<a href="${href}" data-link class="${active===key?'active':''}">${icon(ic)}${label}</a>`).join('')}</nav><div class="sidebar-user"><strong>${esc(user.name)}</strong><span>${user.role==='admin'?'ผู้ดูแลระบบ':'เจ้าหน้าที่'}</span><button id="logout" class="button ghost small" type="button">${icon('logout')} ออกจากระบบ</button></div></aside><div class="admin-content">${content}</div></div>`;
  $('#logout')?.addEventListener('click',async()=>{try{await api('/api/admin/logout',{method:'POST',body:{}});user=null;go('/admin/login');}catch(e){toast(e.message);}});
}
function adminTop(title,subtitle,actions=''){return `<div class="admin-top"><div><h1 class="page-title">${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="button-row">${actions}</div></div>`;}
function adminCourseRows(courses){return courses.map(c=>`<tr><td class="title-cell"><a href="/admin/courses/${c.id}/registrations" data-link>${esc(c.title)}</a><span class="cell-sub">${esc(c.speaker)}</span></td><td>${fmt(c.start_at)}<span class="cell-sub">${time(c.start_at)} น. · ${formatLabels[c.format]}</span></td><td>${badge(c.status)}</td><td><strong>${number(c.used)}</strong> / ${number(c.capacity)}<span class="cell-sub">เหลือ ${number(c.remaining)} ที่</span></td><td><div class="cell-actions"><a class="button secondary small" href="/admin/courses/${c.id}/registrations" data-link>${icon('users')} ผู้สมัคร</a>${user.role==='admin'?`<a class="button secondary small" href="/admin/courses/${c.id}/edit" data-link aria-label="แก้ไข ${esc(c.title)}">${icon('edit')}</a>`:''}</div></td></tr>`).join('');}
function courseTable(courses,title='หลักสูตรทั้งหมด'){return `<section class="table-panel"><div class="table-toolbar"><h2>${title} <span class="muted small-text">(${courses.length})</span></h2><a href="/" data-link class="text-link">ดูหน้าสาธารณะ ${icon('external')}</a></div><div class="table-scroll"><table><thead><tr><th>หลักสูตร / วิทยากร</th><th>วันเวลาอบรม</th><th>สถานะ</th><th>ที่นั่ง</th><th>จัดการ</th></tr></thead><tbody>${courses.length?adminCourseRows(courses):'<tr><td colspan="5" class="table-empty">ยังไม่มีหลักสูตร เริ่มสร้างหลักสูตรแรกของคุณ</td></tr>'}</tbody></table></div></section>`;}
async function overview(version){
  const [summary,courses]=await Promise.all([api('/api/admin/summary'),api('/api/admin/courses')]);if(version!==renderVersion)return;document.title='ภาพรวมระบบ — เรียนรู้';
  const total=Object.values(summary.registrations).reduce((a,b)=>a+b,0);
  const stats=[['หลักสูตรทั้งหมด',summary.courses,'book','หลักสูตรที่ใช้งานอยู่'],['ผู้สมัครทั้งหมด',total,'users','รวมทุกสถานะการสมัคร'],['ยืนยันแล้ว',summary.registrations.confirmed||0,'check','ผู้สมัครที่ได้รับการยืนยัน'],['รออนุมัติ',summary.registrations.pending||0,'clock',`คิวสำรอง ${number(summary.registrations.waitlisted)} คน`]];
  adminShell(`${adminTop('ภาพรวมการอบรม',`ยินดีต้อนรับ ${user.name} · ${fmt(new Date())}`,user.role==='admin'?'<a href="/admin/courses/new" data-link class="button primary">'+icon('plus')+' สร้างหลักสูตร</a>':'')}<div class="stats-grid">${stats.map(([label,value,ic,note])=>`<article class="stat"><div class="stat-label">${label}</div><span class="stat-icon">${icon(ic)}</span><div class="stat-number">${number(value)}</div><div class="stat-note">${note}</div></article>`).join('')}</div>${summary.emails.failed?`<div class="notice warning">${icon('mail')} มีอีเมลส่งไม่สำเร็จ ${number(summary.emails.failed)} รายการ ${user.role==='admin'?'<a href="/admin/emails" data-link>ตรวจสอบการส่งอีเมล</a>':''}</div>`:''}${courseTable(courses,'หลักสูตรและการลงทะเบียน')}${config.email_mode==='local'?'<p class="small-text muted">โหมดพัฒนา · อีเมลถูกบันทึกใน data/outbox ตั้งค่า SMTP เพื่อส่งจริง</p>':''}`);
}
async function adminCourses(version){const courses=await api('/api/admin/courses');if(version!==renderVersion)return;document.title='จัดการหลักสูตร — เรียนรู้';
  adminShell(`${adminTop('หลักสูตรและรอบอบรม','จัดการหลักสูตร รายชื่อผู้สมัคร และจำนวนที่นั่ง',user.role==='admin'?'<a href="/admin/courses/new" data-link class="button primary">'+icon('plus')+' สร้างหลักสูตร</a>':'')}<div class="roster-controls"><div class="search-control">${icon('search')}<label class="visually-hidden" for="admin-search">ค้นหาหลักสูตร</label><input id="admin-search" placeholder="ค้นหาหลักสูตรหรือวิทยากร…"></div></div><div id="admin-course-table">${courseTable(courses)}</div>`,'courses');$('#admin-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();$('#admin-course-table').innerHTML=courseTable(courses.filter(c=>`${c.title} ${c.speaker}`.toLowerCase().includes(q)));});
}
const localDate=value=>value?new Date(new Date(value).getTime()+7*3600000).toISOString().slice(0,16):'';
const utcDate=value=>new Date(`${value}:00+07:00`).toISOString();
async function courseEditor(id,version){
  if(user.role!=='admin')throw Object.assign(new Error('เฉพาะผู้ดูแลระบบเท่านั้น'),{status:403});
  const c=id?await api(`/api/admin/courses/${id}`):{};if(version!==renderVersion)return;
  let customFields=c.fields||[];document.title=`${id?'แก้ไข':'สร้าง'}หลักสูตร — เรียนรู้`;
  adminShell(`${adminTop(id?'แก้ไขหลักสูตร':'สร้างหลักสูตรใหม่','กำหนดรายละเอียด รอบอบรม และการรับสมัคร',id?'<button type="button" id="duplicate-course" class="button secondary">'+icon('copy')+' ทำสำเนา</button>':'')}<form id="course-form">${formError()}<section class="panel form-section"><h2>รายละเอียดหลักสูตร</h2><div class="form-grid">${field('title','ชื่อหลักสูตร','text',{required:true,value:c.title,full:true,attrs:'maxlength="200"'})}${field('slug','URL หลักสูตร','text',{required:true,value:c.slug,hint:'ตัวอักษรอังกฤษตัวเล็ก ตัวเลข และขีดกลาง เช่น ai-workshop',attrs:'pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="150"'})}${field('speaker','วิทยากร','text',{required:true,value:c.speaker,attrs:'maxlength="200"'})}${field('description','รายละเอียด','textarea',{required:true,value:c.description,full:true,attrs:'minlength="10" maxlength="20000"'})}${field('cover_image','URL รูปปก (ไม่บังคับ)','url',{value:c.cover_image,full:true,placeholder:'https://…',hint:'เว้นว่างเพื่อใช้ภาพกราฟิกของระบบ',attrs:'pattern="https://.*"'})}${field('format','รูปแบบการอบรม','select',{required:true,value:c.format||'onsite',choices:Object.entries(formatLabels)})}${field('location','สถานที่','text',{value:c.location,attrs:'maxlength="500"'})}${field('online_url','ลิงก์ห้องเรียนออนไลน์','url',{value:c.online_url,full:true,attrs:'pattern="https://.*"',hint:'ส่งให้ผู้สมัครที่ยืนยันแล้วเท่านั้น'})}</div></section><section class="panel form-section"><h2>กำหนดการและการรับสมัคร</h2><p class="field-hint">เวลาทั้งหมดเป็นเวลาไทย (Asia/Bangkok)</p><div class="form-grid">${field('start_at','เริ่มอบรม','datetime-local',{required:true,value:localDate(c.start_at)})}${field('end_at','สิ้นสุดอบรม','datetime-local',{required:true,value:localDate(c.end_at)})}${field('reg_open_at','เปิดรับสมัคร','datetime-local',{required:true,value:localDate(c.reg_open_at)})}${field('reg_close_at','ปิดรับสมัคร','datetime-local',{required:true,value:localDate(c.reg_close_at)})}${field('capacity','จำนวนที่นั่ง','number',{required:true,value:c.capacity||30,attrs:'min="1" max="100000" step="1"'})}${field('price','ค่าลงทะเบียน (บาท)','number',{required:true,value:c.price??0,attrs:'min="0" max="99999999" step="0.01"',hint:'0 = ฟรี · การชำระเงินออนไลน์อยู่ใน Phase 2'})}${field('cancel_deadline_days','ยกเลิกได้ก่อนเริ่มอบรม (วัน)','number',{required:true,value:c.cancel_deadline_days??1,attrs:'min="0" max="365" step="1"'})}${field('status','สถานะหลักสูตร','select',{value:c.status==='full'?'open':c.status||'draft',choices:[['draft','ฉบับร่าง'],['open','เปิดรับสมัคร'],['closed','ปิดรับสมัคร'],['finished','สิ้นสุดแล้ว']]})}<div class="field full"><label class="checkbox-label"><input name="requires_approval" type="checkbox" ${c.requires_approval?'checked':''}>ต้องได้รับการอนุมัติจากเจ้าหน้าที่ก่อนยืนยันการสมัคร</label></div></div></section><section class="panel form-section"><div class="section-heading"><h2>ฟิลด์เพิ่มเติมในแบบฟอร์ม</h2><button id="add-custom" type="button" class="button secondary small">${icon('plus')} เพิ่มฟิลด์</button></div><div id="custom-fields"></div><p class="field-hint">แก้ไขป้ายชื่อได้โดยไม่เปลี่ยนข้อมูลคำตอบเดิม การลบฟิลด์จะซ่อนฟิลด์นั้นจากฟอร์มและ CSV</p></section><div class="button-row"><button type="submit" class="button primary">บันทึกหลักสูตร</button><a href="/admin/courses" data-link class="button secondary">กลับ</a>${id?'<button type="button" id="delete-course" class="button danger">'+icon('trash')+' ลบหลักสูตร</button>':''}</div></form>`,'courses');
  const readFields=()=>$$('.custom-field-editor').map((el,i)=>({...(customFields[i]?.id?{id:customFields[i].id}:{}),label:$('[data-field-label]',el).value,type:$('[data-field-type]',el).value,options:$('[data-field-options]',el).value.split('\n').map(s=>s.trim()).filter(Boolean),is_required:$('[data-field-required]',el).checked}));
  const drawFields=()=>{
    $('#custom-fields').innerHTML=customFields.length?customFields.map((f,i)=>`<fieldset class="custom-field-editor"><legend class="small-text">ฟิลด์เพิ่มเติม ${i+1}</legend><div class="button-row"><span class="muted small-text">แสดงตามลำดับนี้ในแบบฟอร์ม</span><button type="button" data-remove-field="${i}" class="button danger small">${icon('trash')} ลบฟิลด์</button></div><div class="form-grid"><div class="field"><label for="custom-label-${i}">ชื่อฟิลด์ *</label><input id="custom-label-${i}" data-field-label required maxlength="200" value="${esc(f.label)}"></div><div class="field"><label for="custom-type-${i}">ชนิดข้อมูล</label><select id="custom-type-${i}" data-field-type>${[['text','ข้อความ'],['select','รายการตัวเลือก'],['checkbox','ช่องทำเครื่องหมาย']].map(([v,l])=>`<option value="${v}" ${f.type===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field full"><label for="custom-options-${i}">ตัวเลือก (ใช้สำหรับรายการตัวเลือก · 1 ตัวเลือกต่อบรรทัด)</label><textarea id="custom-options-${i}" data-field-options rows="3">${esc((f.options||[]).join('\n'))}</textarea></div><div class="field full"><label class="checkbox-label"><input type="checkbox" data-field-required ${f.is_required?'checked':''}>จำเป็นต้องกรอก</label></div></div></fieldset>`).join(''):'<p class="small-text muted">ยังไม่มีฟิลด์เพิ่มเติม ใช้เฉพาะข้อมูลพื้นฐานของผู้สมัคร</p>';
    $$('[data-remove-field]').forEach(b=>b.addEventListener('click',()=>{customFields=readFields();customFields.splice(Number(b.dataset.removeField),1);drawFields();}));
  };drawFields();
  $('#add-custom').addEventListener('click',()=>{customFields=readFields();if(customFields.length>=20)return toast('เพิ่มได้ไม่เกิน 20 ฟิลด์');customFields.push({label:'',type:'text',options:[],is_required:false});drawFields();$$('[data-field-label]').at(-1)?.focus();});
  submitForm($('#course-form'),async data=>{
    const body=Object.fromEntries(['title','slug','speaker','description','cover_image','format','location','online_url','status'].map(k=>[k,data.get(k)]));
    for(const k of ['start_at','end_at','reg_open_at','reg_close_at'])body[k]=utcDate(data.get(k));for(const k of ['capacity','price','cancel_deadline_days'])body[k]=Number(data.get(k));body.requires_approval=data.has('requires_approval');body.fields=readFields();
    await api(id?`/api/admin/courses/${id}`:'/api/admin/courses',{method:id?'PUT':'POST',body});toast('บันทึกหลักสูตรเรียบร้อยแล้ว');go('/admin/courses');
  });
  $('#duplicate-course')?.addEventListener('click',async()=>{if(!await confirmAction('สร้างสำเนาหลักสูตรนี้เป็นฉบับร่าง โดยไม่คัดลอกผู้สมัคร?'))return;try{const result=await api(`/api/admin/courses/${id}/duplicate`,{method:'POST',body:{}});go(`/admin/courses/${result.id}/edit`);toast('สร้างสำเนาเป็นฉบับร่างแล้ว');}catch(e){toast(e.message);}});
  $('#delete-course')?.addEventListener('click',async()=>{if(!await confirmAction('หลักสูตรจะถูกซ่อน ผู้สมัครที่เกี่ยวข้องจะถูกยกเลิกและได้รับอีเมลแจ้งยกเลิก',{title:'ลบหลักสูตร'}))return;try{await api(`/api/admin/courses/${id}`,{method:'DELETE',body:{}});go('/admin/courses');toast('ลบหลักสูตรและจัดคิวอีเมลแจ้งผู้สมัครแล้ว');}catch(e){toast(e.message);}});
}
function pagination(data){return `<div class="pagination"><span>ทั้งหมด ${number(data.total)} รายการ · หน้า ${data.page} / ${Math.max(1,Math.ceil(data.total/data.page_size))}</span><div class="button-row"><button type="button" class="button secondary small" data-page="${data.page-1}" ${data.page<=1?'disabled':''}>ก่อนหน้า</button><button type="button" class="button secondary small" data-page="${data.page+1}" ${data.page*data.page_size>=data.total?'disabled':''}>ถัดไป</button></div></div>`;}
async function roster(id,version){
  const courses=await api('/api/admin/courses');const c=courses.find(c=>c.id===id);if(!c)throw new Error('ไม่พบหลักสูตร');if(version!==renderVersion)return;
  document.title=`ผู้สมัคร ${c.title} — เรียนรู้`;
  adminShell(`${adminTop('ผู้สมัครอบรม',c.title,`<button id="export-csv" class="button secondary">${icon('download')} Export CSV</button>${user.role==='admin'?`<a href="/admin/courses/${id}/edit" data-link class="button primary">${icon('edit')} แก้ไขหลักสูตร</a>`:''}`)}<div class="notice">${icon('users')} จำนวนที่นั่ง ${number(c.capacity)} · ผู้ถือที่นั่ง ${number(c.used)} · เหลือ ${number(c.remaining)} ที่นั่ง</div><form id="roster-filter" class="roster-controls"><div class="search-control">${icon('search')}<label class="visually-hidden" for="roster-search">ค้นหาผู้สมัคร</label><input id="roster-search" name="search" placeholder="ค้นหาชื่อ อีเมล หรือรหัสการสมัคร…" maxlength="200"></div><label class="visually-hidden" for="roster-status">สถานะ</label><select id="roster-status" name="status"><option value="">ทุกสถานะ</option>${['pending','confirmed','waitlisted','rejected','cancelled'].map(s=>`<option value="${s}">${labels[s]}</option>`).join('')}</select><label class="visually-hidden" for="roster-sort">เรียงลำดับ</label><select id="roster-sort" name="sort"><option value="newest">ใหม่ที่สุด</option><option value="oldest">เก่าที่สุด</option><option value="name">ชื่อผู้สมัคร</option><option value="waitlist">ลำดับคิวสำรอง</option></select><button type="submit" class="button primary">ค้นหา</button></form><div id="roster-results" aria-live="polite"></div>`,'courses');
  let page=1;let query=new URLSearchParams();let loadVersion=0;
  const load=async()=>{const current=++loadVersion;query=new URLSearchParams(new FormData($('#roster-filter')));query.set('page',page);$('#roster-results').innerHTML='<div class="panel muted">กำลังโหลดรายชื่อ…</div>';
    try{const data=await api(`/api/admin/courses/${id}/registrations?${query}`);if(current!==loadVersion||version!==renderVersion)return;
      $('#roster-results').innerHTML=`<section class="table-panel"><div class="bulk-bar"><label class="checkbox-label"><input type="checkbox" id="select-all">เลือกทั้งหมดในหน้านี้</label><label class="visually-hidden" for="bulk-status">เปลี่ยนสถานะเป็น</label><select id="bulk-status"><option value="confirmed">อนุมัติ / เลื่อนคิวสำรอง</option><option value="rejected">ปฏิเสธ</option><option value="cancelled">ยกเลิก</option><option value="pending">รออนุมัติ</option></select><button type="button" id="apply-bulk" class="button secondary small">ใช้กับรายการที่เลือก</button></div><div class="table-scroll"><table><thead><tr><th>เลือก</th><th>ผู้สมัคร</th><th>การติดต่อ</th><th>หน่วยงาน</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${data.rows.length?data.rows.map(r=>`<tr><td><input type="checkbox" data-registration="${r.id}" aria-label="เลือก ${esc(r.first_name)}"></td><td class="title-cell">${esc(r.title)}${esc(r.first_name)} ${esc(r.last_name)}<span class="cell-sub">${esc(r.code)}</span><span class="cell-sub">${fmt(r.created_at)} ${time(r.created_at)}</span></td><td>${esc(r.email)}<span class="cell-sub">${esc(r.phone)}</span></td><td>${esc(r.organization)}<span class="cell-sub">${esc(r.position)}</span></td><td>${badge(r.status)}${r.status==='waitlisted'?`<span class="cell-sub">ลำดับ ${number(r.waitlist_position)}</span>`:''}${r.reason?`<span class="cell-sub">${esc(r.reason)}</span>`:''}</td><td><div class="cell-actions">${['cancelled','rejected'].includes(r.status)?'<span class="muted">—</span>':`<button type="button" class="button secondary small" data-status="confirmed" data-id="${r.id}" ${r.status==='confirmed'?'disabled':''}>${r.status==='waitlisted'?'เลื่อนคิว':'อนุมัติ'}</button><button type="button" class="button danger small" data-status="rejected" data-id="${r.id}">ปฏิเสธ</button><button type="button" class="button secondary small" data-status="cancelled" data-id="${r.id}">ยกเลิก</button>`}</div></td></tr>`).join(''):'<tr><td colspan="6" class="table-empty">ไม่พบผู้สมัครตามเงื่อนไขที่เลือก</td></tr>'}</tbody></table></div>${pagination(data)}</section>`;
      $('#select-all').addEventListener('change',e=>$$('[data-registration]').forEach(c=>c.checked=e.target.checked));
      for(const r of data.rows){
        if(!c.fields.length)continue;
        const answers=JSON.parse(r.custom_answers);const details=document.createElement('details');details.className='small-text';
        details.innerHTML=`<summary>คำตอบเพิ่มเติม / PDPA</summary>${c.fields.map(f=>`<div>${esc(f.label)}: ${esc(typeof answers[f.id]==='boolean'?(answers[f.id]?'ใช่':'ไม่ใช่'):(answers[f.id]||'—'))}</div>`).join('')}<div>ยินยอม ${esc(fmt(r.pdpa_consented_at))} ${esc(time(r.pdpa_consented_at))} น.</div>`;
        $(`[data-registration="${r.id}"]`).closest('tr').children[1].append(details);
      }
      $$('[data-page]').forEach(b=>b.addEventListener('click',()=>{page=Number(b.dataset.page);void load();}));
      const update=async(ids,status)=>{if(!ids.length)return toast('กรุณาเลือกรายการก่อน');const answer=await confirmAction(`เปลี่ยน ${ids.length} รายการเป็น “${labels[status]}” ?`,{reason:true});if(!answer)return;
        try{await api('/api/admin/registrations/bulk/status',{method:'PATCH',body:{ids,status,reason:answer.reason}});toast('เปลี่ยนสถานะและจัดคิวอีเมลแล้ว');void render();}catch(e){toast(e.message);}
      };
      $('#apply-bulk').addEventListener('click',()=>void update($$('[data-registration]:checked').map(c=>c.dataset.registration),$('#bulk-status').value));
      $$('[data-status]').forEach(b=>b.addEventListener('click',()=>void update([b.dataset.id],b.dataset.status)));
    }catch(e){if(current===loadVersion&&version===renderVersion)$('#roster-results').innerHTML=`<div class="notice error">${esc(e.message)}</div>`;}
  };
  $('#roster-filter').addEventListener('submit',e=>{e.preventDefault();page=1;void load();});
  $('#export-csv').addEventListener('click',async()=>{const button=$('#export-csv');button.disabled=true;try{const response=await fetch(`/api/admin/courses/${id}/export.csv?${query}`,{credentials:'same-origin'});if(!response.ok)throw new Error('ดาวน์โหลดไม่สำเร็จ กรุณาเข้าสู่ระบบใหม่');const blob=await response.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`registrations-${c.slug}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('ดาวน์โหลด CSV แล้ว');}catch(e){toast(e.message);}finally{button.disabled=false;}});
  await load();
}
async function usersPage(version){
  if(user.role!=='admin')throw Object.assign(new Error('เฉพาะผู้ดูแลระบบเท่านั้น'),{status:403});
  const users=await api('/api/admin/users');if(version!==renderVersion)return;document.title='ผู้ใช้ระบบ — เรียนรู้';
  adminShell(`${adminTop('จัดการผู้ใช้ระบบ','กำหนดบัญชีและสิทธิ์สำหรับผู้ดูแลและเจ้าหน้าที่')}<section class="table-panel"><div class="table-scroll"><table><thead><tr><th>ชื่อ / อีเมล</th><th>สิทธิ์</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${users.map(u=>`<tr><td>${esc(u.name)}<span class="cell-sub">${esc(u.email)}</span></td><td>${u.role==='admin'?'ผู้ดูแลระบบ':'เจ้าหน้าที่'}</td><td>${u.is_active?'<span class="badge confirmed">ใช้งานอยู่</span>':'<span class="badge cancelled">ปิดใช้งาน</span>'}</td><td><button class="button secondary small" data-edit-user="${u.id}">${icon('edit')} แก้ไข</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2 id="user-form-title">เพิ่มผู้ใช้ใหม่</h2><form id="user-form">${formError()}<div class="form-grid">${field('name','ชื่อ','text',{required:true,attrs:'maxlength="200"'})}${field('email','อีเมล','email',{required:true,attrs:'maxlength="254" autocomplete="off"'})}${field('password','รหัสผ่าน','password',{required:true,attrs:'minlength="12" maxlength="100" autocomplete="new-password"',hint:'อย่างน้อย 12 ตัวอักษร'})}${field('role','สิทธิ์','select',{choices:[['staff','เจ้าหน้าที่'],['admin','ผู้ดูแลระบบ']]})}<div class="field full" id="user-active-wrap" hidden><label class="checkbox-label"><input name="is_active" type="checkbox" checked>เปิดใช้งานบัญชี</label></div></div><div class="button-row"><button type="submit" class="button primary">บันทึกผู้ใช้</button><button type="button" id="new-user" class="button secondary" hidden>ยกเลิกการแก้ไข</button></div></form></section>`,'users');
  let editId=null;
  $$('[data-edit-user]').forEach(b=>b.addEventListener('click',()=>{const u=users.find(u=>u.id===b.dataset.editUser);editId=u.id;const form=$('#user-form');form.elements.name.value=u.name;form.elements.email.value=u.email;form.elements.email.disabled=true;form.elements.role.value=u.role;form.elements.is_active.checked=!!u.is_active;form.elements.password.value='';form.elements.password.required=false;$('#user-active-wrap').hidden=false;$('#new-user').hidden=false;$('#user-form-title').textContent=`แก้ไขบัญชี ${u.name}`;form.scrollIntoView({behavior:'smooth'});}));
  $('#new-user').addEventListener('click',()=>void render());
  submitForm($('#user-form'),async data=>{const body={name:data.get('name'),role:data.get('role'),...(editId?{is_active:data.has('is_active')}:{email:data.get('email')}),...(data.get('password')?{password:data.get('password')}:{})};await api(editId?`/api/admin/users/${editId}`:'/api/admin/users',{method:editId?'PATCH':'POST',body});toast('บันทึกผู้ใช้แล้ว');if(editId===user.id){user=null;go('/admin/login');}else await render();});
}
async function logsPage(kind,version){
  if(user.role!=='admin')throw Object.assign(new Error('เฉพาะผู้ดูแลระบบเท่านั้น'),{status:403});
  const isMail=kind==='emails';document.title=`${isMail?'การส่งอีเมล':'ประวัติการทำรายการ'} — เรียนรู้`;
  adminShell(`${adminTop(isMail?'การส่งอีเมล':'ประวัติการทำรายการ',isMail?'ตรวจสอบคิว สถานะ และการลองส่งซ้ำ':'บันทึกผู้ดำเนินการ รายการ และวันเวลาที่เปลี่ยนแปลงข้อมูล')}${isMail&&config.email_mode==='local'?'<div class="notice">โหมดพัฒนา: สถานะ “บันทึกในเครื่อง” หมายถึงไฟล์ .eml ใน data/outbox ยังไม่ได้ส่งอีเมลจริง</div>':''}<div id="logs-table"></div>`,kind);
  const load=async(page=1)=>{const data=await api(`/api/admin/${kind}?page=${page}`);if(version!==renderVersion)return;
    $('#logs-table').innerHTML=`<div class="table-panel"><div class="table-scroll"><table><thead><tr>${(isMail?['ผู้รับ / เรื่อง','สถานะ','จำนวนครั้ง','เวลา','จัดการ']:['ผู้ดำเนินการ','การกระทำ','ข้อมูล','เวลา']).map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${data.rows.length?data.rows.map(r=>isMail?`<tr><td class="title-cell">${esc(r.subject)}<span class="cell-sub">${esc(r.to_email)}</span></td><td>${badge(r.status)}${r.error?`<span class="cell-sub">${esc(r.error)}</span>`:''}</td><td>${r.attempts} / 5</td><td>${fmt(r.created_at)}<span class="cell-sub">${time(r.created_at)} น.</span></td><td>${r.status==='failed'?`<button class="button secondary small" data-retry="${r.id}">${icon('refresh')} ลองส่งอีกครั้ง</button>`:'—'}</td></tr>`:`<tr><td>${esc(r.actor_name||'ระบบ / ผู้สมัคร')}</td><td>${esc(r.action)}<span class="cell-sub">${esc(r.ip||'')}</span></td><td class="title-cell">${esc(r.entity)}<span class="cell-sub">${esc(r.entity_id)}</span>${r.before_data||r.after_data?`<details><summary class="small-text">รายละเอียดการเปลี่ยนแปลง</summary><pre class="audit-data">ก่อน: ${esc(r.before_data||'—')}\nหลัง: ${esc(r.after_data||'—')}</pre></details>`:''}</td><td>${fmt(r.created_at)}<span class="cell-sub">${time(r.created_at)} น.</span></td></tr>`).join(''):`<tr><td colspan="5" class="table-empty">ยังไม่มีรายการ</td></tr>`}</tbody></table></div>${pagination(data)}</div>`;
    $$('[data-page]').forEach(b=>b.addEventListener('click',()=>void load(Number(b.dataset.page)).catch(e=>toast(e.message))));
    $$('[data-retry]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await api(`/api/admin/emails/${b.dataset.retry}/retry`,{method:'POST',body:{}});toast('จัดคิวส่งอีกครั้งแล้ว');await load(page);}catch(e){toast(e.message);b.disabled=false;}}));
  };await load();
}
function privacyPage(){
  document.title='นโยบายข้อมูลส่วนบุคคล — เรียนรู้';
  $('#main').innerHTML=`<div class="container"><article class="privacy-copy">${breadcrumb([{label:'นโยบายข้อมูลส่วนบุคคล'}])}<h1 class="page-title">นโยบายข้อมูลส่วนบุคคล</h1><p class="subtitle">สำหรับการลงทะเบียนและเข้าร่วมอบรม</p><section class="panel"><h2>ข้อมูลที่เราจัดเก็บ</h2><p>คำนำหน้า ชื่อ นามสกุล อีเมล เบอร์โทร หน่วยงาน ตำแหน่ง คำตอบเพิ่มเติมที่ผู้จัดกำหนด ข้อมูลการสมัคร และเวลาที่คุณยินยอมตามนโยบายนี้ ระบบจัดเก็บ IP และบันทึกการใช้งานเท่าที่จำเป็นสำหรับป้องกันการใช้งานผิดปกติและตรวจสอบการดำเนินงาน</p><h2>วัตถุประสงค์</h2><p>เพื่อดำเนินการสมัคร จัดสรรที่นั่ง ติดต่อแจ้งผลและรายละเอียดการอบรม ส่งข้อความเตือน และจัดทำรายชื่อผู้เข้าอบรม การแจ้งข่าวสารนี้เกี่ยวข้องกับหลักสูตรที่คุณสมัคร</p><h2>การเข้าถึงและผู้ให้บริการ</h2><p>จำกัดการเข้าถึงเฉพาะผู้ดูแลและเจ้าหน้าที่ที่ได้รับสิทธิ์ ข้อมูลที่จำเป็นอาจผ่านผู้ให้บริการโฮสต์ฐานข้อมูล อีเมล และระบบตรวจสอบผู้ใช้งานอัตโนมัติที่ผู้จัดตั้งค่า ผู้จัดต้องแจ้งรายชื่อผู้ให้บริการและเงื่อนไขการโอนข้อมูลที่เกี่ยวข้องก่อนใช้งานจริง</p><h2>ระยะเวลาเก็บข้อมูล</h2><p>นโยบายเริ่มต้นกำหนดเก็บข้อมูลการสมัครไม่เกิน ${number(config.retention_days)} วันหลังสิ้นสุดหลักสูตร เมื่อพ้นระยะเวลา ผู้จัดจะดำเนินการลบหรือทำให้ไม่สามารถระบุตัวบุคคล เว้นแต่จำเป็นต้องเก็บตามหน้าที่ทางกฎหมาย การลบข้อมูลและสำเนาสำรองดำเนินการโดยผู้ดูแลตามรอบการเก็บรักษาขององค์กร</p><h2>สิทธิของคุณ</h2><p>คุณสามารถขอเข้าถึง แก้ไข ลบ ถอนความยินยอม หรือสอบถามการใช้ข้อมูล โดยติดต่อ <a href="mailto:${esc(config.privacy_contact)}">${esc(config.privacy_contact)}</a> โปรดระบุรหัสการสมัครและอีเมลที่ใช้สมัครเพื่อยืนยันตัวตน การถอนความยินยอมอาจทำให้ไม่สามารถดำเนินการสมัครหรือแจ้งข่าวสารที่จำเป็นได้</p><h2>การรักษาข้อมูล</h2><p>ลิงก์ดูสถานะเฉพาะบุคคลเป็นข้อมูลลับ กรุณาไม่ส่งต่อ ผู้ดูแลใช้บัญชีเฉพาะบุคคล ระบบจำกัดสิทธิ์ตามบทบาท บันทึกการเปลี่ยนแปลง และใช้การเชื่อมต่อ HTTPS เมื่อเปิดใช้งานจริง</p></section></article></div>`;
}
async function render(){
  const version=++renderVersion;const path=decodeURI(location.pathname).replace(/\/$/,'')||'/';shell();$('#main').innerHTML='<div class="page-loading" role="status">กำลังโหลด…</div>';
  try{
    if(path==='/')return await home(version);
    if(path==='/privacy')return privacyPage();
    if(path==='/admin/login'){if(user){go('/admin');return;}return loginPage();}
    if(path.startsWith('/admin')){
      try{user=await api('/api/admin/me');}catch(e){if(e.status===401){user=null;go('/admin/login');return;}throw e;}
      if(version!==renderVersion)return;shell();
      if(path==='/admin')return await overview(version);
      if(path==='/admin/courses')return await adminCourses(version);
      if(path==='/admin/courses/new')return await courseEditor(null,version);
      let match=path.match(/^\/admin\/courses\/([^/]+)\/edit$/);if(match)return await courseEditor(match[1],version);
      match=path.match(/^\/admin\/courses\/([^/]+)\/registrations$/);if(match)return await roster(match[1],version);
      if(path==='/admin/users')return await usersPage(version);
      if(path==='/admin/emails'||path==='/admin/audit')return await logsPage(path.split('/').at(-1),version);
    }
    if(path==='/registrations')return await lookupPage('',version);
    let match=path.match(/^\/registrations\/([^/]+)$/);if(match)return await lookupPage(match[1],version);
    match=path.match(/^\/courses\/([^/]+)\/register$/);if(match)return await registrationForm(match[1],version);
    match=path.match(/^\/courses\/([^/]+)$/);if(match)return await courseDetail(match[1],version);
    throw Object.assign(new Error('ไม่พบหน้าที่ต้องการ'),{status:404});
  }catch(e){if(version!==renderVersion)return;if(e.status===401){user=null;go('/admin/login');return;}$('#main').innerHTML=`<div class="container page-section">${empty(e.status===403?'คุณไม่มีสิทธิ์เข้าถึงหน้านี้':'ไม่สามารถแสดงหน้านี้ได้',e.message,'<a class="button primary" href="/" data-link>กลับหน้าหลัก</a><button class="button secondary" id="retry-page" type="button">ลองใหม่</button>')}</div>`;$('#retry-page')?.addEventListener('click',()=>void render());}
}
document.addEventListener('click',event=>{const link=event.target.closest('a[data-link]');if(!link||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||event.button!==0)return;event.preventDefault();go(link.getAttribute('href'));});
window.addEventListener('popstate',()=>void render());
window.addEventListener('unhandledrejection',event=>{console.error(event.reason);toast(event.reason?.message||'ระบบขัดข้อง กรุณาลองใหม่');});
(async()=>{try{config=await api('/api/config');try{user=await api('/api/admin/me');}catch{/* public visitor */}await render();}catch(e){$('#main').innerHTML=`<div class="container page-section">${empty('เชื่อมต่อระบบไม่สำเร็จ',e.message)}<button class="button primary" id="reload-app">ลองใหม่</button></div>`;$('#reload-app').addEventListener('click',()=>location.reload());}})();
